/* ---------- auditoria ---------- */
function audit(area,acao,det){try{S.audit=S.audit||[];const s=SESSAO||{};S.audit.unshift({q:Date.now(),u:s.u||'—',area,acao,det:det?String(det).slice(0,300):'',v:typeof VIEW!=='undefined'?VIEW:''});if(S.audit.length>5000)S.audit.length=5000}catch(_){}}
let _audUlt={k:'',q:0};
function auditEdicao(){const k=VIEW+'|'+(S.turmaAtiva||'');const n=Date.now();if(_audUlt.k===k&&n-_audUlt.q<90000){if(S.audit&&S.audit[0]&&S.audit[0].acao==='Edição'){S.audit[0].q=n;S.audit[0].n=(S.audit[0].n||1)+1}return}
  _audUlt={k,q:n};const t=T();audit(TITLES[VIEW]||VIEW,'Edição',t?t.nome+' · '+t.disciplina:'')}
function defAuditoria(){const L=S.audit||[];const f=UI.audF||{};const users=[...new Set(L.map(x=>x.u))];const areas=[...new Set(L.map(x=>x.area))].sort();
  const F=L.filter(x=>(!f.u||x.u===f.u)&&(!f.a||x.area===f.a)&&(!f.q||normT(x.acao+' '+x.det+' '+x.area).includes(normT(f.q)))&&(!f.d||isoData(new Date(x.q))>=f.d));
  return `<div class="card"><div class="row"><h2 style="margin:0">${ic('shield',18)} Auditoria e Registos</h2><span class="sp1"></span><button class="btn" id="au-csv">${ic('download',15)} Exportar CSV</button><button class="btn" id="au-pdf">${ic('file',15)} Exportar PDF</button>${(SESSAO||{}).papel==='admin'?`<button class="btn dng" id="au-lim">${ic('trash',15)} Limpar &gt; 1 ano</button>`:''}</div>
    <p class="hint" style="margin:10px 0 0">Regista quem fez o quê e quando: inícios e fins de sessão (e tentativas falhadas), edições por secção, importações, exportações, PDF, eliminações e restauros, mudanças de organização, escolas, contas e correções de integridade. ${L.length} registos guardados (máx. 5000).</p>
    <div class="row" style="gap:8px;margin-top:12px;flex-wrap:wrap"><select id="au-u"><option value="">Todos os utilizadores</option>${users.map(u=>`<option ${f.u===u?'selected':''}>${esc(u)}</option>`).join('')}</select><select id="au-a"><option value="">Todas as áreas</option>${areas.map(a=>`<option ${f.a===a?'selected':''}>${esc(a)}</option>`).join('')}</select><input type="date" id="au-d" value="${f.d||''}" title="Desde"><input type="search" id="au-q" value="${esc(f.q||'')}" placeholder="Procurar…" style="flex:1;min-width:160px"></div>
    <div class="tblw" style="margin-top:12px"><table class="lst"><thead><tr><th>Data e hora</th><th>Utilizador</th><th>Área</th><th>Ação</th><th>Detalhe</th></tr></thead><tbody>${F.slice(0,400).map(x=>`<tr><td style="white-space:nowrap">${new Date(x.q).toLocaleString('pt-PT')}</td><td>${esc(x.u)}</td><td>${esc(x.area)}</td><td><b>${esc(x.acao)}</b>${x.n>1?` <span class="mut">×${x.n}</span>`:''}</td><td class="mut">${esc(x.det)}</td></tr>`).join('')||'<tr><td colspan="5" class="mut">Sem registos.</td></tr>'}</tbody></table></div>${F.length>400?`<p class="hint">A mostrar 400 de ${F.length}. Use os filtros ou exporte.</p>`:''}</div>`}
function bindAuditoria(){const f=UI.audF=UI.audF||{};const up=()=>{f.u=$('#au-u').value;f.a=$('#au-a').value;f.d=$('#au-d').value;f.q=$('#au-q').value;vDefinicoes()};['au-u','au-a','au-d'].forEach(i=>$('#'+i).onchange=up);$('#au-q').onchange=up;
  $('#au-csv').onclick=()=>{download('EduSpruce-auditoria.csv',csv([['Data','Utilizador','Área','Ação','Detalhe','Vezes'],...(S.audit||[]).map(x=>[new Date(x.q).toLocaleString('pt-PT'),x.u,x.area,x.acao,x.det,x.n||1])]),'text/csv');audit('Auditoria','Exportação CSV','')};
  $('#au-pdf').onclick=()=>pdfDocumento({titulo:'Registo de Auditoria',subtitulo:(S.audit||[]).length+' registos',paisagem:true,blocos:[{tabela:{cab:['Data e hora','Utilizador','Área','Ação','Detalhe'],larg:[.17,.13,.15,.18,.37],linhas:(S.audit||[]).slice(0,1500).map(x=>[new Date(x.q).toLocaleString('pt-PT'),x.u,x.area,x.acao+(x.n>1?' ×'+x.n:''),x.det])}}]},'EduSpruce-auditoria');
  const l=$('#au-lim');if(l)l.onclick=()=>{if(!confirm('Apagar registos com mais de 1 ano?'))return;const lim=Date.now()-365*864e5;S.audit=(S.audit||[]).filter(x=>x.q>=lim);audit('Auditoria','Registos antigos apagados','');saveNow();vDefinicoes()}}

/* ---------- Início: widgets, favoritos e tarefas ---------- */
const WIDGETS=[['tarefas','Próximas Tarefas','checks'],['contagem','Contagem do Período','clock'],['matrizes','Matrizes a Enviar','file'],['favoritos','Favoritos','star'],['datas','Datas Importantes','flag'],['testes','Próximos Testes','target'],['turmas','As Minhas Turmas','users'],['reunioes','Reuniões','meet'],['aniversarios','Aniversários','star']];
const cfgInicio=()=>{const c=S.cfg.inicio=S.cfg.inicio||{};c.ordem=c.ordem||WIDGETS.map(w=>w[0]);WIDGETS.forEach(w=>{if(!c.ordem.includes(w[0])){if(w[0]==='tarefas')c.ordem.unshift(w[0]);else c.ordem.push(w[0])}});c.ocultos=c.ocultos||[];return c};
const widgetOn=k=>!cfgInicio().ocultos.includes(k);
function personalizarInicioDlg(){const c=cfgInicio();const html=()=>`<div class="ed"><p class="hint" style="margin-top:0">Escolha os cartões do Início e a ordem (setas).</p><div class="wlist">${c.ordem.map((k,i)=>{const w=WIDGETS.find(x=>x[0]===k);if(!w)return '';return `<div class="wli"><label class="chk"><input type="checkbox" data-wg="${k}" ${widgetOn(k)?'checked':''}> ${ic(w[2],15)} ${w[1]}</label><span class="sp1"></span><button class="btn sm ico" data-wu="${i}" ${i?'':'disabled'} aria-label="Subir">${ic('arrowUp',14)}</button><button class="btn sm ico rot" data-wd="${i}" ${i<c.ordem.length-1?'':'disabled'} aria-label="Descer">${ic('arrowUp',14)}</button></div>`}).join('')}</div>
   <div class="row" style="margin-top:12px"><button class="btn" id="wg-rep">${ic('refresh',14)} Repor</button><span class="sp1"></span><button class="btn pri" id="wg-ok">${ic('check',15)} Concluído</button></div></div>`;
  const abre=()=>{openDrawer('Personalizar o Início',html());$$('[data-wg]').forEach(b=>b.onchange=()=>{c.ocultos=c.ocultos.filter(x=>x!==b.dataset.wg);if(!b.checked)c.ocultos.push(b.dataset.wg);save()});
    $$('[data-wu]').forEach(b=>b.onclick=()=>{const i=+b.dataset.wu;[c.ordem[i-1],c.ordem[i]]=[c.ordem[i],c.ordem[i-1]];save();abre()});$$('[data-wd]').forEach(b=>b.onclick=()=>{const i=+b.dataset.wd;[c.ordem[i+1],c.ordem[i]]=[c.ordem[i],c.ordem[i+1]];save();abre()});
    $('#wg-rep').onclick=()=>{delete S.cfg.inicio;save();personalizarInicioDlg()};$('#wg-ok').onclick=()=>{closeDrawer();go('inicio')}};abre()}
/* favoritos */
const favs=()=>S.cfg.favoritos=S.cfg.favoritos||[];
const favChave=()=>VIEW+'|'+(NEEDS_T.includes(VIEW)?S.turmaAtiva||'':'');
function alternarFavorito(){const k=favChave();const L=favs();const i=L.findIndex(f=>f.k===k);if(i>=0){L.splice(i,1);toast('Removido dos favoritos')}else{const t=T();L.push({k,v:VIEW,turma:NEEDS_T.includes(VIEW)?S.turmaAtiva:null,esc:escAtiva(),t:(TITLES[VIEW]||VIEW)+(t&&NEEDS_T.includes(VIEW)?' — '+t.nome:'')});toast('Adicionado aos favoritos (aparece no Início)','ok')}save();favBtn()}
function favBtn(){const b=$('#favBtn');if(!b)return;const on=favs().some(f=>f.k===favChave());b.classList.toggle('on',on);b.title=on?'Remover dos favoritos':'Adicionar aos favoritos';b.setAttribute('aria-pressed',on);b.style.display=VIEW==='inicio'?'none':''}
function abrirFavorito(i){const f=favs()[i];if(!f)return;if(f.esc)S.escolaAtiva=f.esc;if(f.turma)S.turmaAtiva=f.turma;go(f.v)}
function widgetFavoritos(){const L=favs();return `<div class="card wfav"><div class="row"><h2 style="margin:0">${ic('star',18)} Favoritos</h2><span class="sp1"></span><span class="mut" style="font-size:12.5px">use ☆ na barra para juntar</span></div>
  ${L.length?`<div class="favg">${L.map((f,i)=>`<button class="favi" data-fav="${i}"><span>${ic('star',15)}</span><b>${esc(f.t)}</b><span class="favx" data-favx="${i}" title="Remover" aria-label="Remover">${ic('x',12)}</span></button>`).join('')}</div>`:'<p class="mut" style="margin:0">Ainda não há favoritos. Abra uma secção (ex.: a avaliação de uma turma) e toque na estrela da barra de cima.</p>'}</div>`}
/* tarefas */
const tarefas=()=>S.todo=S.todo||[];
function widgetTarefas(){const hj=isoData(new Date());const L=tarefas().slice().sort((a,b)=>(a.feito-b.feito)||((a.prazo||'9')).localeCompare(b.prazo||'9'));const pend=L.filter(x=>!x.feito);
  const rt=(A()?reunioes(A()):[]).flatMap(r=>(r.decisoes||[]).filter(d=>!d.ok).map(d=>({d,r})));
  return `<div class="card wtodo"><div class="row"><h2 style="margin:0">${ic('checks',18)} As Minhas Tarefas</h2><span class="sp1"></span><span class="mut" style="font-size:12.5px">${pend.length} por fazer</span></div>
   <div class="tdnew"><input id="td-t" placeholder="Nova tarefa… (Enter)"><input type="date" id="td-p" title="Prazo"><button class="btn sm pri" id="td-ok" aria-label="Acrescentar">${ic('plus',14)}</button></div>
   <div class="tdl">${L.slice(0,12).map(x=>`<div class="tdi ${x.feito?'ok':''} ${!x.feito&&x.prazo&&x.prazo<hj?'atr':''}"><input type="checkbox" data-tdk="${x.id}" ${x.feito?'checked':''} aria-label="Feita"><span class="tdt">${esc(x.t)}${x.prazo?`<span class="mut"> · ${esc(contagem(x.prazo))}</span>`:''}</span><button class="btn sm ico" data-tdx="${x.id}" aria-label="Apagar">${ic('x',12)}</button></div>`).join('')}
   ${rt.slice(0,4).map(({d,r})=>`<div class="tdi reun"><span class="tdr">${ic('meet',13)}</span><span class="tdt">${esc(d.t)}<span class="mut"> · ${esc(reunTitulo(r,A()))}${d.prazo?' · '+esc(contagem(d.prazo)):''}</span></span></div>`).join('')}</div>
   ${!L.length&&!rt.length?'<p class="mut" style="margin:8px 0 0">Sem tarefas. As tarefas das reuniões aparecem aqui automaticamente.</p>':''}</div>`}
function bindWidgets(){const add=()=>{const t=$('#td-t');if(!t||!t.value.trim())return;tarefas().push({id:uid(),t:t.value.trim(),prazo:$('#td-p').value||'',feito:false,criada:Date.now()});save();go('inicio');setTimeout(()=>$('#td-t')&&$('#td-t').focus(),50)};
  if($('#td-ok')){$('#td-ok').onclick=add;$('#td-t').onkeydown=e=>{if(e.key==='Enter')add()}}
  $$('[data-tdk]').forEach(c=>c.onchange=()=>{const x=tarefas().find(z=>z.id===c.dataset.tdk);x.feito=c.checked;x.feitaEm=c.checked?Date.now():null;save();go('inicio')});
  $$('[data-tdx]').forEach(b=>b.onclick=()=>{S.todo=tarefas().filter(z=>z.id!==b.dataset.tdx);save();go('inicio')});
  $$('[data-fav]').forEach(b=>b.onclick=e=>{const x=e.target.closest('[data-favx]');if(x){e.stopPropagation();favs().splice(+x.dataset.favx,1);save();go('inicio');return}abrirFavorito(+b.dataset.fav)});
  const pz=$('#in-pers');if(pz)pz.onclick=personalizarInicioDlg}

/* =====================================================================
   v0.34 (B) — ficha do aluno por separadores, planta da sala,
               gestão de aulas e sumários (substituições e reposições)
   ===================================================================== */
const mesmoAluno=(x,y)=>x===y||(x.processo&&y.processo&&String(x.processo)===String(y.processo))||(!x.processo||!y.processo)&&normT(x.nome)===normT(y.nome);
function ocorrenciasAluno(al){const L=[];S.anos.forEach(an=>{prepAno(an);an.turmas.forEach(t=>t.alunos.forEach(x=>{if(mesmoAluno(x,al))L.push({an,t,x})}))});return L}
const FICHA_TABS=[['geral','user','Identificação'],['turma','users','Turma e Fotografia'],['disc','book','Disciplinas'],['msai','shield','Medidas de Apoio (MSAI)'],['notas','chart','Classificações'],['assid','calcheck','Assiduidade'],
  ['inst','clipboard','Trabalhos e Instrumentos'],['obs','pen','Observações'],['ativ','award','Participação'],['cont','chat','Contactos'],['docs','folder','Documentos'],['interv','refresh','Intervenções'],['exp','download','Exportar']];
const TIPOS_FALTA={injust:'Injustificada',just:'Justificada',atraso:'Atraso',material:'Falta de material',disc:'Disciplinar'};
const TIPOS_INTERV=['Contacto com o encarregado de educação','Tutoria / acompanhamento','Apoio educativo','Ocorrência disciplinar','Reunião','Encaminhamento (SPO / EMAEI)','Outra'];
function fichaAluno(id,tab){const t=T();if(!t)return;const a=t.alunos.find(x=>x.id===id);if(!a)return;tab=tab||UI.fichaTab||'geral';if(!FICHA_TABS.some(x=>x[0]===tab))tab='geral';UI.fichaTab=tab;
  const base=tab==='msai'?'msai':'geral';fichaAluno0(id,base);UI.fichaTab=tab;
  const dw=$('#dw-b');const tb=dw.querySelector('.tabs');if(!tb)return;
  tb.className='tabs fichatabs';tb.innerHTML=FICHA_TABS.map(([k,i,l])=>`<button data-ft="${k}" class="${tab===k?'on':''}">${ic(i,14)} ${l}</button>`).join('');
  $$('#dw-b [data-ft]').forEach(b=>b.onclick=()=>{const y=tb.scrollLeft;fichaAluno(id,b.dataset.ft);const n=$('#dw-b .fichatabs');if(n)n.scrollLeft=y});
  const on=tb.querySelector('.on');if(on)on.scrollIntoView({inline:'center',block:'nearest'});
  if(tab==='geral'||tab==='msai'){if(tab==='geral'){/* Identificação: campos adicionais antes do resto */
      tb.insertAdjacentHTML('afterend',`<div class="g2 fident"><div><label>Nome completo</label><input data-fx="nome" value="${esc(a.nome)}"></div><div><label>N.º</label><input data-fx="num" value="${esc(a.num)}" inputmode="numeric"></div>
        <div><label>N.º de processo</label><input data-fx="processo" value="${esc(a.processo||'')}"></div><div><label>N.º interno</label><input data-fx="numInterno" value="${esc(a.numInterno||'')}"></div>
        <div><label>E-mail da escola</label><input data-fx="emailEscola" type="email" inputmode="email" value="${esc(a.emailEscola||'')}" placeholder="aluno@escola.edu.azores.gov.pt"></div><div><label>Data de nascimento</label><input data-fx="nasc" type="date" value="${esc(a.nasc||'')}"></div></div>`);
      bindFx(a,id)}
    return}
  // separadores novos: substituem o conteúdo depois da barra de separadores
  let n=tb.nextSibling;while(n){const nx=n.nextSibling;n.remove();n=nx}
  tb.insertAdjacentHTML('afterend',`<div class="ftab">${fichaTab(t,a,tab)}</div>`);bindFichaTab(t,a,tab,id)}
function bindFx(a,id){$$('[data-fx]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.fx;if(k==='nome')setNome(a,el.value.trim());else a[k]=el.value.trim();save();audit('Alunos','Ficha alterada',a.nome+' · '+k);if(VIEW==='alunos')vAlunos()}))}
function fichaTab(t,a,tab){const hj=isoData(new Date());const lst=(k)=>a[k]=a[k]||[];
  if(tab==='turma'){const oc=ocorrenciasAluno(a).filter(o=>o.an===A());return `<dl class="ftkv"><div><dt>Turma</dt><dd>${esc(a.origem||t.nome)} · N.º ${esc(numAl(a))}${a.cargo?' · '+(a.cargo==='D'?(a.genero==='F'?'Delegada':'Delegado'):(a.genero==='F'?'Subdelegada':'Subdelegado')):''}</dd></div><div><dt>Escola e Ano Letivo</dt><dd>${esc(nomeEscola(escolaDe(t)))} · ${esc((A()||{}).nome||'')}</dd></div>${idade(a.nasc)||a.genero?`<div><dt>Idade e Sexo</dt><dd>${idade(a.nasc)?idade(a.nasc)+' anos · ':''}${a.genero==='F'?'Feminino':'Masculino'}</dd></div>`:''}</dl>
    <h3>Diretor(a) de Turma</h3><p style="margin:0">${(n=>dtDe(A(),n)?esc(profNome(dtDe(A(),n))):'—')(a.origem||t.nome)}${souDT(A(),a.origem||t.nome)?' <span class="tag dt">'+tituloDT(S.cfg.professor)+'</span>':''}</p>
    <h3>Nas minhas turmas este ano</h3>${oc.map(o=>`<div class="lin"><b>${esc(o.t.nome)}</b> · ${esc(o.t.disciplina)} <span class="mut">${o.x.frequenta?'frequenta':'não frequenta'}</span></div>`).join('')}`}
  if(tab==='percurso'){const auto=ocorrenciasAluno(a).filter(o=>o.an!==A()).map(o=>({ano:o.an.nome,turma:o.x.origem||o.t.nome,esc:nomeEscola(comEscola(escId(escolaDe(o.t)),()=>escolaDe(o.t))),res:(()=>{const per=o.an.org==='semestre'?2:3;const f=ponderada(o.t,pctsFinal(o.t,o.x.id,per));return f!=null?o.t.disciplina+': '+fmtNota(o.t,f)+' (nível '+nivel(o.t,f)+')':o.t.disciplina})(),auto:true}));
    const man=lst('percurso');return `<p class="hint" style="margin-top:0">O percurso junta automaticamente os anos letivos anteriores registados nesta app e as entradas acrescentadas à mão (outras escolas, retenções, mudanças de curso).</p>
    <div class="tblw"><table class="lst"><thead><tr><th>Ano letivo</th><th>Ano/Turma</th><th>Escola</th><th>Resultado / observações</th><th></th></tr></thead><tbody>
    ${[...auto,...man.map((m,i)=>({...m,i}))].sort((x,y)=>String(y.ano).localeCompare(String(x.ano))).map(m=>`<tr><td><b>${esc(m.ano)}</b></td><td>${esc(m.turma||'')}</td><td>${esc(m.esc||'')}</td><td>${esc(m.res||'')}${m.auto?' <span class="tag">automático</span>':''}</td><td>${m.auto?'':`<button class="btn sm ico dng" data-fdel="percurso|${m.i}" aria-label="Apagar">${ic('x',12)}</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="mut">Sem registos.</td></tr>'}</tbody></table></div>
    <div class="fadd g4"><input id="fp-ano" placeholder="2024/2025"><input id="fp-t" placeholder="8.º B"><input id="fp-e" placeholder="Escola"><input id="fp-r" placeholder="Transitou / Retido / Observações"><button class="btn sm pri" id="fp-ok">${ic('plus',14)}</button></div>`}
  if(tab==='disc'){const oc=ocorrenciasAluno(a).filter(o=>o.an===A());return `<div class="tblw"><table class="lst"><thead><tr><th>Disciplina</th><th>Turma</th><th>Escola</th><th>Frequenta</th><th>Classificação atual</th></tr></thead><tbody>${oc.map(o=>{const per=perAtual(o.t);const f=ponderada(o.t,pctsFinal(o.t,o.x.id,per));return `<tr><td><b>${esc(o.t.disciplina)}</b></td><td>${esc(o.x.origem||o.t.nome)}</td><td class="mut">${esc(nomeEscola(escolaDe(o.t)))}</td><td>${o.x.frequenta?'Sim':'Não'}</td><td>${f!=null?esc(fmtNota(o.t,f))+' · nível '+nivel(o.t,f):'—'}</td></tr>`}).join('')}</tbody></table></div>
    <h3>Outras disciplinas (registo manual)</h3><textarea data-fl="outrasDisc" placeholder="ex.: Português, Matemática A, Físico-Química A…">${esc(a.outrasDisc||'')}</textarea>`}
  if(tab==='notas'){const P=periodos();const rows=t.dominios.map(d=>[d.nome,d.peso+'%',...P.map(p=>pctD(t,domPer(t,a.id,d.id,p))||'—')]);const fin=P.map(p=>ponderada(t,pctsPer(t,a.id,p)));
    const pts=fin.map((f,i)=>f==null?null:[i,f]).filter(Boolean);const W=420,H=120;const sx=i=>20+i*((W-40)/Math.max(1,P.length-1)),sy=f=>H-16-f*(H-32);
    return `<div class="tblw"><table class="lst"><thead><tr><th>Domínio</th><th>Peso</th>${P.map(p=>`<th>${perNome(p)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td>${i?esc(c):'<b>'+esc(c)+'</b>'}</td>`).join('')}</tr>`).join('')}
     <tr class="tot"><td><b>Classificação</b></td><td></td>${fin.map(f=>`<td><b>${f!=null?esc(fmtNota(t,f))+' · '+nivel(t,f):'—'}</b></td>`).join('')}</tr></tbody></table></div>
     <h3>Evolução</h3>${pts.length?`<svg class="fevo" viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Evolução das classificações"><line x1="20" x2="${W-20}" y1="${sy(.5)}" y2="${sy(.5)}" class="sl"/><polyline points="${pts.map(([i,f])=>sx(i)+','+sy(f)).join(' ')}"/>${pts.map(([i,f])=>`<circle cx="${sx(i)}" cy="${sy(f)}" r="4"/><text x="${sx(i)}" y="${sy(f)-9}" text-anchor="middle">${esc(fmtNota(t,f))}</text>`).join('')}${P.map((p,i)=>`<text x="${sx(i)}" y="${H-2}" text-anchor="middle" class="lb">${p}.º</text>`).join('')}</svg>`:'<p class="mut">Ainda sem classificações.</p>'}`}
  if(tab==='assid'){const F=lst('faltasAl').slice().sort((x,y)=>y.data.localeCompare(x.data));const tot=k=>F.filter(f=>f.tipo===k).reduce((s,f)=>s+(+f.tempos||1),0);
    return `<div class="kpis fk">${Object.entries(TIPOS_FALTA).map(([k,l])=>`<div class="kpi"><div class="l">${l}</div><div class="v">${tot(k)}</div></div>`).join('')}</div>
    <div class="fadd g4"><input type="date" id="fa-d" value="${hj}"><input id="fa-t" type="number" min="1" max="8" value="1" inputmode="numeric" title="Tempos"><select id="fa-tp">${Object.entries(TIPOS_FALTA).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><input id="fa-o" placeholder="Observação"><button class="btn sm pri" id="fa-ok">${ic('plus',14)}</button></div>
    <div class="tblw"><table class="lst"><thead><tr><th>Data</th><th>Tempos</th><th>Tipo</th><th>Observação</th><th></th></tr></thead><tbody>${F.map(f=>`<tr><td>${esc(fmtIsoL(f.data))}</td><td>${esc(f.tempos)}</td><td><span class="tag ${f.tipo==='injust'||f.tipo==='disc'?'bad':''}">${esc(TIPOS_FALTA[f.tipo]||f.tipo)}</span></td><td class="mut">${esc(f.obs||'')}</td><td><button class="btn sm ico dng" data-fdelid="faltasAl|${f.id}" aria-label="Apagar">${ic('x',12)}</button></td></tr>`).join('')||'<tr><td colspan="5" class="mut">Sem faltas registadas.</td></tr>'}</tbody></table></div>`}
  if(tab==='inst'){const L=t.instrumentos.slice().sort((x,y)=>String(x.data||'').localeCompare(String(y.data||'')));return `<div class="tblw"><table class="lst"><thead><tr><th>Instrumento</th><th>Tipo</th><th>${perW()}</th><th>Data</th><th>Classificação</th></tr></thead><tbody>${L.map(i=>{const v=instTotal(i,a.id),M=instMax(i);return `<tr><td><b>${esc(i.nome)}</b></td><td>${esc(i.tipo)}</td><td>${esc(i.periodo)}.º</td><td>${esc(fmtIso(i.data)||'—')}</td><td>${v!=null&&M?`<b>${nf(v)}</b>/${nf(M)} · ${Math.round(100*v/M)}%`:'<span class="mut">por classificar</span>'}</td></tr>`}).join('')||'<tr><td colspan="5" class="mut">Sem instrumentos.</td></tr>'}</tbody></table></div>`}
  if(tab==='obs'){return `<label>Observações gerais</label><textarea data-fl="obs" rows="5">${esc(a.obs||'')}</textarea>${periodos().map(p=>`<label style="margin-top:10px">${perNome(p)}</label><textarea data-flp="obsPer|${p}" rows="3">${esc((a.obsPer||{})[p]||'')}</textarea>`).join('')}`}
  if(tab==='ativ'){const L=lst('atividades');return `<div class="fadd g4"><input type="date" id="fv-d" value="${hj}"><input id="fv-a" placeholder="Atividade (ex.: Clube de Ciência, Visita de estudo)"><input id="fv-p" placeholder="Participação / papel"><input id="fv-o" placeholder="Observação"><button class="btn sm pri" id="fv-ok">${ic('plus',14)}</button></div>
    ${L.slice().sort((x,y)=>y.data.localeCompare(x.data)).map(x=>`<div class="lin"><b>${esc(x.atividade)}</b> <span class="mut">${esc(fmtIsoL(x.data))}${x.papel?' · '+esc(x.papel):''}${x.obs?' · '+esc(x.obs):''}</span><span class="sp1"></span><button class="btn sm ico dng" data-fdelid="atividades|${x.id}" aria-label="Apagar">${ic('x',12)}</button></div>`).join('')||'<p class="mut">Sem participações registadas.</p>'}`}
  if(tab==='cont'){const C=lst('contactos');return `<label class="chk"><input type="checkbox" data-fck="contactoAutorizado" ${a.contactoAutorizado?'checked':''}> Contactos autorizados (RGPD) — sem esta autorização os contactos não são exportados</label>
    <div class="g2" style="margin-top:10px"><div><label>Encarregado de educação</label><input data-fl="eeNome" value="${esc(a.eeNome||'')}"></div><div><label>Parentesco</label><input data-fl="eeParent" value="${esc(a.eeParent||'')}" placeholder="Mãe, Pai, Avó…"></div>
    <div><label>Telefone</label><input data-fl="eeContacto" inputmode="tel" value="${esc(a.eeContacto||'')}"></div><div><label>E-mail do encarregado de educação</label><input data-fl="email" type="email" value="${esc(a.email||'')}" autocapitalize="none"></div><div><label>E-mail do aluno</label><input data-fl="emailAluno" type="email" value="${esc(a.emailAluno||'')}" autocapitalize="none" placeholder="de preferência o institucional"></div><div style="grid-column:1/-1"><label>Morada</label><input data-fl="morada" value="${esc(a.morada||'')}"></div></div>
    <h3>Outros responsáveis</h3><div class="fadd g4"><input id="fc-n" placeholder="Nome"><input id="fc-p" placeholder="Parentesco"><input id="fc-t" placeholder="Telefone"><input id="fc-e" placeholder="E-mail"><button class="btn sm pri" id="fc-ok">${ic('plus',14)}</button></div>
    ${C.map(x=>`<div class="lin"><b>${esc(x.nome)}</b> <span class="mut">${esc([x.parent,x.tel,x.email].filter(Boolean).join(' · '))}</span><span class="sp1"></span><button class="btn sm ico dng" data-fdelid="contactos|${x.id}" aria-label="Apagar">${ic('x',12)}</button></div>`).join('')}`}
  if(tab==='docs'){const D=lst('documentos');return `<div class="row" style="gap:8px"><button class="btn pri" id="fd-up">${ic('upload',15)} Anexar Documento</button><input type="file" id="fd-f" multiple hidden><span class="hint" style="margin:0">PDF, Word, imagens… (até 8 MB cada, guardados neste dispositivo)</span></div>
    ${D.map(d=>`<div class="lin"><span class="fdi">${ic(/pdf/.test(d.tipo)?'file':/image/.test(d.tipo)?'image':'folder',16)}</span><b>${esc(d.nome)}</b> <span class="mut">${esc(fmtBytes(d.tam))} · ${new Date(d.q).toLocaleDateString('pt-PT')}${d.cat?' · '+esc(d.cat):''}</span><span class="sp1"></span><button class="btn sm" data-fdopen="${d.id}">${ic('access',14)} Abrir</button><button class="btn sm ico dng" data-fddel="${d.id}" aria-label="Apagar">${ic('x',12)}</button></div>`).join('')||'<p class="mut" style="margin-top:10px">Sem documentos (RTP, PEI, relatórios médicos, autorizações…).</p>'}`}
  if(tab==='interv'){const L=lst('intervencoes');return `<div class="fadd g4"><input type="date" id="fi-d" value="${hj}"><select id="fi-t">${TIPOS_INTERV.map(x=>`<option>${esc(x)}</option>`).join('')}</select><input id="fi-x" placeholder="Descrição"><input id="fi-r" placeholder="Responsável" value="${esc(profNome(S.cfg.professor))}"><button class="btn sm pri" id="fi-ok">${ic('plus',14)}</button></div>
    <div class="tl">${L.slice().sort((x,y)=>y.data.localeCompare(x.data)).map(x=>`<div class="tli"><span class="tld">${esc(fmtIso(x.data))}</span><div><b>${esc(x.tipo)}</b><div>${esc(x.desc)}</div><span class="mut">${esc(x.resp||'')}</span></div><button class="btn sm ico dng" data-fdelid="intervencoes|${x.id}" aria-label="Apagar">${ic('x',12)}</button></div>`).join('')||'<p class="mut">Sem intervenções registadas.</p>'}</div>`}
  if(tab==='port'){const L=lst('portefolio');return `<div class="fadd g4"><input id="fo-t" placeholder="Título do trabalho"><input type="date" id="fo-d" value="${hj}"><input id="fo-l" placeholder="Ligação (opcional)"><input id="fo-n" placeholder="Apreciação / nota"><button class="btn sm pri" id="fo-ok">${ic('plus',14)}</button></div>
    <div class="row" style="gap:8px;margin:8px 0"><button class="btn sm" id="fo-up">${ic('upload',14)} Juntar ficheiro ao portefólio</button><input type="file" id="fo-f" hidden></div>
    <div class="pfg">${L.slice().sort((x,y)=>y.data.localeCompare(x.data)).map(x=>`<div class="pfi">${x.thumb?`<img src="${x.thumb}" alt="">`:`<span class="pfic">${ic(x.doc?'file':'star',22)}</span>`}<b>${esc(x.titulo)}</b><span class="mut">${esc(fmtIsoL(x.data))}${x.nota?' · '+esc(x.nota):''}</span><div class="row" style="gap:4px">${x.link?`<a class="btn sm" href="${esc(x.link)}" target="_blank" rel="noopener">${ic('access',13)}</a>`:''}${x.doc?`<button class="btn sm" data-fdopen="${x.doc}">${ic('access',13)}</button>`:''}<button class="btn sm ico dng" data-fdelid="portefolio|${x.id}" aria-label="Apagar">${ic('x',12)}</button></div></div>`).join('')||'<p class="mut">Portefólio vazio.</p>'}</div>`}
  if(tab==='exp'){return `<p class="hint" style="margin-top:0">Escolha a informação a incluir. Os contactos só são incluídos se estiverem autorizados; as medidas de apoio e a assiduidade são dados sensíveis — inclua-os apenas quando o destinatário tiver direito a eles.</p>
    <div class="expsel">${[['ident','Identificação',1],['turma','Turma e diretor(a) de turma',1],['percurso','Percurso escolar',1],['disc','Disciplinas frequentadas',1],['notas','Classificações',1],['assid','Assiduidade',0],['inst','Trabalhos e instrumentos',1],['msai','Medidas de apoio (sensível)',0],['obs','Observações do professor',0],['ativ','Participação em atividades',1],['cont','Contactos (se autorizados)',0],['interv','Histórico de intervenções',0],['port','Portefólio',1]].map(([k,l,d])=>`<label class="chk"><input type="checkbox" data-ex="${k}" ${d?'checked':''}> ${l}</label>`).join('')}</div>
    <div class="row" style="margin-top:12px;gap:8px"><button class="btn pri" id="fx-pdf">${ic('file',15)} Exportar PDF</button><button class="btn" id="fx-json">${ic('download',15)} Exportar Dados (JSON)</button></div>`}
  return ''}
const fmtBytes=b=>!b?'':b<1024?b+' B':b<1048576?(b/1024).toFixed(0)+' KB':(b/1048576).toFixed(1)+' MB';
const lerFicheiroURL=f=>new Promise((ok,ko)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>ko(r.error);r.readAsDataURL(f)});
function guardarDoc(dataURL){const id='doc:'+uid();FOTOS[id]=dataURL;idbPor(id,dataURL);return id}
function abrirDoc(id,nome){const u=FOTOS[id];if(!u)return toast('O ficheiro não está disponível neste dispositivo','erro');const [h,b]=u.split(',');const mime=(h.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const bin=atob(b);const arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
  const url=URL.createObjectURL(new Blob([arr],{type:mime}));if(/pdf|image|audio|text|video/.test(mime)){const w=window.open(url,'_blank');if(!w){const x=document.createElement('a');x.href=url;x.download=nome||'documento';x.click()}}else{const x=document.createElement('a');x.href=url;x.download=nome||'documento';x.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}
function bindFichaTab(t,a,tab,id){const re=()=>{save();fichaAluno(id,tab);if(VIEW==='alunos'&&['notas','turma'].includes(tab))vAlunos()};const v=s=>($(s)||{}).value||'';
  $$('[data-fl]').forEach(el=>el.addEventListener('change',()=>{a[el.dataset.fl]=el.value;save();audit('Alunos','Ficha alterada',a.nome+' · '+el.dataset.fl)}));
  $$('[data-flp]').forEach(el=>el.addEventListener('change',()=>{const [k,p]=el.dataset.flp.split('|');a[k]=a[k]||{};a[k][p]=el.value;save()}));
  $$('[data-fck]').forEach(el=>el.onchange=()=>{a[el.dataset.fck]=el.checked;save();audit('Alunos','Autorização de contactos',a.nome+': '+(el.checked?'sim':'não'))});
  $$('[data-fdel]').forEach(b=>b.onclick=()=>{const [k,i]=b.dataset.fdel.split('|');a[k].splice(+i,1);re()});
  $$('[data-fdelid]').forEach(b=>b.onclick=()=>{const [k,i]=b.dataset.fdelid.split('|');a[k]=(a[k]||[]).filter(x=>x.id!==i);re()});
  const add=(btn,k,obj,req)=>{const b=$(btn);if(b)b.onclick=()=>{const o=obj();if(req&&!o[req])return toast('Preencha o campo principal','erro');(a[k]=a[k]||[]).push({id:uid(),...o});audit('Alunos','Registo acrescentado',a.nome+' · '+k);re()}};
  add('#fp-ok','percurso',()=>({ano:v('#fp-ano'),turma:v('#fp-t'),esc:v('#fp-e'),res:v('#fp-r')}),'ano');
  add('#fa-ok','faltasAl',()=>({data:v('#fa-d'),tempos:+v('#fa-t')||1,tipo:v('#fa-tp'),obs:v('#fa-o')}),'data');
  add('#fv-ok','atividades',()=>({data:v('#fv-d'),atividade:v('#fv-a'),papel:v('#fv-p'),obs:v('#fv-o')}),'atividade');
  add('#fc-ok','contactos',()=>({nome:v('#fc-n'),parent:v('#fc-p'),tel:v('#fc-t'),email:v('#fc-e')}),'nome');
  add('#fi-ok','intervencoes',()=>({data:v('#fi-d'),tipo:v('#fi-t'),desc:v('#fi-x'),resp:v('#fi-r')}),'desc');
  add('#fo-ok','portefolio',()=>({titulo:v('#fo-t'),data:v('#fo-d'),link:v('#fo-l'),nota:v('#fo-n')}),'titulo');
  const ff=$('#ft-foto');if(ff){ff.onclick=()=>$('#ft-f').click();$('#ft-f').onchange=e=>{const f=e.target.files[0];if(f)fotoDeFicheiro(f).then(u=>{a.foto=u;re()}).catch(er=>alert(er.message))}}
  const up=$('#fd-up');if(up){up.onclick=()=>$('#fd-f').click();$('#fd-f').onchange=async e=>{for(const f of e.target.files){if(f.size>8*1048576){toast(f.name+': maior que 8 MB','erro');continue}const u=await lerFicheiroURL(f);(a.documentos=a.documentos||[]).push({id:guardarDoc(u),nome:f.name,tipo:f.type,tam:f.size,q:Date.now()});audit('Alunos','Documento anexado',a.nome+' · '+f.name)}re()}}
  const pu=$('#fo-up');if(pu){pu.onclick=()=>$('#fo-f').click();$('#fo-f').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>8*1048576)return toast('Maior que 8 MB','erro');const u=await lerFicheiroURL(f);
    let thumb='';if(/image/.test(f.type)){try{thumb=await fotoDeFicheiro(f)}catch(_){}}(a.portefolio=a.portefolio||[]).push({id:uid(),titulo:v('#fo-t')||f.name,data:v('#fo-d')||isoData(new Date()),nota:v('#fo-n'),doc:guardarDoc(u),thumb});re()}}
  $$('[data-fdopen]').forEach(b=>b.onclick=()=>{const d=(a.documentos||[]).find(x=>x.id===b.dataset.fdopen)||{};abrirDoc(b.dataset.fdopen,d.nome)});
  $$('[data-fddel]').forEach(b=>b.onclick=()=>{if(!confirm('Apagar o documento?'))return;a.documentos=(a.documentos||[]).filter(x=>x.id!==b.dataset.fddel);delete FOTOS[b.dataset.fddel];re()});
  const xp=$('#fx-pdf');if(xp)xp.onclick=()=>{const sel=$$('[data-ex]').filter(x=>x.checked).map(x=>x.dataset.ex);exportarFichaPdf(t,a,sel)};
  const xj=$('#fx-json');if(xj)xj.onclick=()=>{const sel=new Set($$('[data-ex]').filter(x=>x.checked).map(x=>x.dataset.ex));const o={nome:a.nome,num:a.num,turma:a.origem||t.nome};if(sel.has('ident'))Object.assign(o,{processo:a.processo,numInterno:a.numInterno,emailEscola:a.emailEscola,nascimento:a.nasc,genero:a.genero});
    ['percurso','atividades','intervencoes','portefolio','faltasAl'].forEach(k=>{const m={percurso:'percurso',atividades:'ativ',intervencoes:'interv',portefolio:'port',faltasAl:'assid'}[k];if(sel.has(m))o[k]=(a[k]||[]).map(({doc,thumb,...r})=>r)});
    if(sel.has('cont')&&a.contactoAutorizado)Object.assign(o,{ee:a.eeNome,eeParentesco:a.eeParent,telefone:a.eeContacto,email:a.email,morada:a.morada,outros:a.contactos});if(sel.has('obs'))o.observacoes=a.obs;
    download('Aluno '+a.nome+'.json',JSON.stringify(o,null,1),'application/json');audit('Alunos','Exportação da ficha (JSON)',a.nome)}}
function exportarFichaPdf(t,a,sel){const S_=new Set(sel);const B=[];const P=periodos();const e=escolaDe(t);
  B.push({kv:[['Nome',a.nome],['Turma',(a.origem||t.nome)+' · N.º '+a.num],...(S_.has('ident')?[['N.º de processo',a.processo||'—'],['N.º interno',a.numInterno||'—'],['E-mail da escola',a.emailEscola||'—'],['Data de nascimento',a.nasc?fmtD(a.nasc)+' ('+idade(a.nasc)+' anos)':'—']]:[])],foto:fotoSrc(a)});
  if(S_.has('turma'))B.push({h:'Turma'},{p:'Diretor(a) de turma: '+(profNome(dtDe(A(),a.origem||t.nome))||'—')+(a.cargo?' · Cargo: '+(a.cargo==='D'?'Delegado(a)':'Subdelegado(a)'):'')});
  if(S_.has('percurso')){const L=ocorrenciasAluno(a).filter(o=>o.an!==A()).map(o=>[o.an.nome,o.x.origem||o.t.nome,o.t.disciplina]).concat((a.percurso||[]).map(m=>[m.ano,m.turma,(m.esc?m.esc+' · ':'')+(m.res||'')]));B.push({h:'Percurso Escolar'},L.length?{tabela:{cab:['Ano letivo','Turma','Observações'],linhas:L,larg:[.2,.2,.6]}}:{p:'Sem registos.'})}
  if(S_.has('disc')){const oc=ocorrenciasAluno(a).filter(o=>o.an===A());B.push({h:'Disciplinas Frequentadas'},{tabela:{cab:['Disciplina','Turma','Frequenta'],linhas:oc.map(o=>[o.t.disciplina,o.x.origem||o.t.nome,o.x.frequenta?'Sim':'Não']),larg:[.5,.25,.25]}})}
  if(S_.has('notas'))B.push({h:'Classificações — '+t.disciplina},{tabela:{cab:['Domínio','Peso',...P.map(perNome)],linhas:[...t.dominios.map(d=>[d.nome,d.peso+'%',...P.map(p=>pctD(t,domPer(t,a.id,d.id,p))||'—')]),['Classificação','',...P.map(p=>{const f=ponderada(t,pctsPer(t,a.id,p));return f!=null?fmtNota(t,f)+' (nível '+nivel(t,f)+')':'—'})]]}});
  if(S_.has('assid')){const F=a.faltasAl||[];B.push({h:'Assiduidade'},F.length?{tabela:{cab:['Data','Tempos','Tipo','Observação'],linhas:F.map(f=>[fmtD(f.data),f.tempos,TIPOS_FALTA[f.tipo]||f.tipo,f.obs||'']),larg:[.2,.12,.25,.43]}}:{p:'Sem faltas registadas.'})}
  if(S_.has('inst'))B.push({h:'Trabalhos e Instrumentos de Avaliação'},{tabela:{cab:['Instrumento','Tipo','Data','Classificação'],linhas:t.instrumentos.map(i=>{const v=instTotal(i,a.id),M=instMax(i);return [i.nome,i.tipo,i.data?fmtD(i.data):'—',v!=null&&M?nf(v)+'/'+nf(M)+' ('+Math.round(100*v/M)+'%)':'—']}),larg:[.35,.25,.15,.25]}});
  if(S_.has('msai')){const m=a.medidas||{};const L=Object.entries(MEDIDAS).flatMap(([k,g])=>(m[k]||[]).map(i=>[g.t,g.l[i]])).concat((a.acomod||[]).map(i=>['Acomodações curriculares',ACOMOD[i]]));B.push({h:'Medidas de Apoio (DL 54/2018)'},L.length?{tabela:{cab:['Tipo','Medida'],linhas:L,larg:[.35,.65]}}:{p:'Sem medidas.'})}
  if(S_.has('obs'))B.push({h:'Observações do Professor'},{p:[a.obs||'',...P.map(p=>(a.obsPer||{})[p]?perNome(p)+': '+a.obsPer[p]:'')].filter(Boolean).join('\n')||'—'});
  if(S_.has('ativ'))B.push({h:'Participação em Atividades'},(a.atividades||[]).length?{tabela:{cab:['Data','Atividade','Participação'],linhas:a.atividades.map(x=>[fmtD(x.data),x.atividade,[x.papel,x.obs].filter(Boolean).join(' · ')]),larg:[.18,.42,.4]}}:{p:'—'});
  if(S_.has('cont'))B.push({h:'Contactos dos Responsáveis'},a.contactoAutorizado?{kv:[['Encarregado de educação',(a.eeNome||'—')+(a.eeParent?' ('+a.eeParent+')':'')],['Telefone',a.eeContacto||'—'],['E-mail',a.email||'—'],['Morada',a.morada||'—'],...(a.contactos||[]).map(c=>[c.parent||'Contacto',[c.nome,c.tel,c.email].filter(Boolean).join(' · ')])]}:{p:'Contactos não incluídos: sem autorização registada.'});
  if(S_.has('interv'))B.push({h:'Histórico de Intervenções'},(a.intervencoes||[]).length?{tabela:{cab:['Data','Tipo','Descrição','Responsável'],linhas:a.intervencoes.map(x=>[fmtD(x.data),x.tipo,x.desc,x.resp||'']),larg:[.14,.26,.42,.18]}}:{p:'—'});
  if(S_.has('port'))B.push({h:'Portefólio'},(a.portefolio||[]).length?{tabela:{cab:['Data','Trabalho','Apreciação'],linhas:a.portefolio.map(x=>[fmtD(x.data),x.titulo,x.nota||'']),larg:[.18,.5,.32]}}:{p:'—'});
  pdfDocumento({titulo:'Ficha Individual do Aluno',subtitulo:a.nome+' · '+t.disciplina,escola:e,turma:t,blocos:B,assinaturas:[profAssin()]},'Ficha '+a.nome);audit('Alunos','Exportação da ficha (PDF)',a.nome)}

